 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not fours or not sixes:
        return out
    r0, r1 = min(r for r, c in fours), max(r for r, c in fours)
    c0, c1 = min(c for r, c in fours), max(c for r, c in fours)
    sr0, sr1 = min(r for r, c in sixes), max(r for r, c in sixes)
    sc0, sc1 = min(c for r, c in sixes), max(c for r, c in sixes)
    # Square marker indicates left/right reflection; wide marker indicates top/bottom reflection.
    horizontal_mirror = (sr1 - sr0) == (sc1 - sc0)
    for r, c in sixes:
        out[r][c] = 0
    if horizontal_mirror:
        marker_c = sum(c for r, c in sixes) / len(sixes)
        source_c = sum(c for r, c in fours) / len(fours)
        if marker_c < source_c:
            for r, c in fours:
                nc = 2 * c0 - 1 - c
                if 0 <= nc < w:
                    out[r][nc] = 4
        else:
            for r, c in fours:
                nc = 2 * c1 + 1 - c
                if 0 <= nc < w:
                    out[r][nc] = 4
    else:
        marker_r = sum(r for r, c in sixes) / len(sixes)
        source_r = sum(r for r, c in fours) / len(fours)
        if marker_r >= source_r:
            for r, c in fours:
                nr = 2 * r1 + 1 - r
                if 0 <= nr < h:
                    out[nr][c] = 4
        else:
            for r, c in fours:
                nr = 2 * r0 - 1 - r
                if 0 <= nr < h:
                    out[nr][c] = 4
    return out
